{
  "analysis": "All three agent workspaces are set up with SKILL.md, inbox/instructions.md, and status.json. Now I need to run each agent in sequence: data-collector first, then analyst, then writer. Each agent must update their status.json to 'completed' when done.",
  "plan": "Run the data-collector agent first. I'll create a Python script to read the raw_market_data.json, extract the metrics, and write to outbox/extracted_metrics.json, then update status.json to completed.",
  "commands": [
    {
      "keystrokes": "cd agents/data-collector && cat inbox/instructions.md\n",
      "duration": 0.1
    },
    {
      "keystrokes": "python3 << 'PYEOF'
import json
import os

# Update status to running
with open('status.json', 'w') as f:
    json.dump({"status": "running"}, f)

# Read raw market data
with open('inbox/raw_market_data.json', 'r') as f:
    raw_data = json.load(f)

# Extract all metrics - the raw data is already structured
extracted_metrics = {
    "report_metadata": {
        "report_date": raw_data.get("report_date"),
        "analysis_id": raw_data.get("analysis_id")
    },
    "overall_market": {
        "total_market_size_bn": raw_data.get("total_market_size_bn"),
        "overall_market_growth": raw_data.get("overall_market_growth")
    },
    "sectors": raw_data.get("sectors", [])
}

# Write output
with open('outbox/extracted_metrics.json', 'w') as f:
    json.dump(extracted_metrics, f, indent=2)

# Update status to completed
with open('status.json', 'w') as f:
    json.dump({"status": "completed"}, f)

print("Data collector completed successfully")
PYEOF
",
